import{_ as t,o as a,c as s,a5 as r}from"./chunks/framework.BZzouRtU.js";const i="/study/images/game/game-states-and-pause.svg",u=JSON.parse('{"title":"ゲームの状態とポーズ — タイトル・プレイ・結果を切り替える","description":"","frontmatter":{"title":"ゲームの状態とポーズ — タイトル・プレイ・結果を切り替える","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"タイトル、プレイ中、ポーズ、結果画面を例に、状態、遷移、受け付ける入力、止める更新と動かすUIを説明する。","aliases":["ゲーム状態","game state","状態遷移","ポーズ","pause","タイトル画面","結果画面","timeScale","unscaledDeltaTime","ステートマシン"],"verification":"Unity 6.0のTime.timeScale・unscaledDeltaTimeと、状態管理・入力の既存詳解に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/game-states-and-pause.md","filePath":"game/basics/game-states-and-pause.md"}'),n={name:"game/basics/game-states-and-pause.md"};function d(o,e,c,l,m,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ゲームの状態とポーズ-—-タイトル・プレイ・結果を切り替える" tabindex="-1">ゲームの状態とポーズ — タイトル・プレイ・結果を切り替える <a class="header-anchor" href="#ゲームの状態とポーズ-—-タイトル・プレイ・結果を切り替える" aria-label="Permalink to &quot;ゲームの状態とポーズ — タイトル・プレイ・結果を切り替える&quot;">​</a></h1><p>同じ決定ボタンでも、タイトル画面ではゲームを始め、ポーズ画面では再開するなど、場面によって意味が変わります。<strong>ゲームの状態</strong>は、その時点でどんな処理を進め、どんな操作を受け付けるかを整理するために使います。ここでは小さな一人用ゲームを例にします。<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a></p><h2 id="状態ごとに、することを決める" tabindex="-1">状態ごとに、することを決める <a class="header-anchor" href="#状態ごとに、することを決める" aria-label="Permalink to &quot;状態ごとに、することを決める&quot;">​</a></h2><table tabindex="0"><thead><tr><th>この例の状態</th><th>進める処理</th><th>受け付ける操作の例</th></tr></thead><tbody><tr><td><strong>タイトル</strong></td><td>メニューの表示。</td><td>開始、設定の変更。</td></tr><tr><td><strong>プレイ中</strong></td><td>プレイヤーや敵、ゲームの時間の更新。</td><td>移動、攻撃、ポーズ。</td></tr><tr><td><strong>ポーズ中</strong></td><td>ポーズメニューの表示と操作。</td><td>再開、設定、タイトルへ戻る。</td></tr><tr><td><strong>結果</strong></td><td>スコアやクリア結果の表示。</td><td>リトライ、タイトルへ戻る。</td></tr></tbody></table><p>一つの状態から別の状態へ切り替えることを<strong>遷移</strong>と呼びます。「開始が選ばれたらプレイ中へ」「HPが0になったら結果へ」のように、きっかけと切り替え先を決めます。このように状態と遷移で動作を整理する考え方が<strong>ステートマシン</strong>です。<a href="/study/game/patterns/state-machines.html">有限ステートマシンの詳解</a></p><figure class="study-figure"><img src="'+i+'" alt="説明用のゲームはタイトルから開始してプレイ中になる。プレイ中から結果へ、またはポーズへ進む。ポーズから再開でき、結果からタイトルへ戻る。各状態で入力や更新の方針を変える。" width="760" height="446" loading="lazy"><figcaption>この例では、主となる状態を一つ選びます。複数のメニューを重ねる場合などは、階層やスタックを使う構成もあります。<a href="/study/images/game/game-states-and-pause.svg" target="_blank" rel="noopener noreferrer">ゲーム状態の図を拡大</a></figcaption></figure><h2 id="シーンの切り替えとの関係" tabindex="-1">シーンの切り替えとの関係 <a class="header-anchor" href="#シーンの切り替えとの関係" aria-label="Permalink to &quot;シーンの切り替えとの関係&quot;">​</a></h2><p><strong>シーン</strong>は配置や設定をまとめる単位です。<strong>状態</strong>は、今どんな振る舞いをするかを決めるために使います。一つのシーンの上にポーズメニューを表示することも、タイトル用とプレイ用のシーンを分けることもできます。状態の名前と、読み込むシーンの構成を対応させて設計します。<a href="/study/game/basics/scenes-and-components.html">シーンとコンポーネント</a></p><p>例えばポーズへ入るときにはメニューを表示し、プレイヤー用の移動操作を止めます。再開するときは、メニューを閉じ、ゲームの更新と入力を戻します。状態へ入るとき・出るときの処理をまとめると、止めたものを戻し忘れていないか追えます。<a href="/study/game/basics/input-actions-and-devices.html">入力アクションと機器</a> · <a href="/study/game/basics/ui-layout-and-interaction.html">UIの表示と操作</a></p><h2 id="ポーズでは何を止めるか" tabindex="-1">ポーズでは何を止めるか <a class="header-anchor" href="#ポーズでは何を止めるか" aria-label="Permalink to &quot;ポーズでは何を止めるか&quot;">​</a></h2><p>「ゲームの時間を止める」「敵の更新を止める」「移動や攻撃の操作を受け付けない」「メニューは操作できる」といった方針を、それぞれ決めます。オンライン通信や保存中の処理などがある場合は、その処理をポーズ中も進めるかも確認します。</p><p>Unityの<code>Time.timeScale</code>は、ゲーム内で時間が進む倍率です。<code>0</code>にすると、通常の<code>Time.deltaTime</code>を使う時間の進行が止まり、<code>FixedUpdate</code>や<code>WaitForSeconds</code>で待っているコルーチンの再開にも影響します。入力を受け付けるか、UIを表示するかといったゲームの規則は、状態に応じて制御します。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Time-timeScale.html" target="_blank" rel="noreferrer">UnityのTime.timeScale</a></p><p>ポーズ中もメニューを動かす例では、時間倍率に影響されない<code>Time.unscaledDeltaTime</code>などを使えます。どの時間を使って動く処理かを見分けると、ゲーム内の時間とメニューの動きを別々に扱えます。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Time-unscaledDeltaTime.html" target="_blank" rel="noreferrer">UnityのTime.unscaledDeltaTime</a></p><h2 id="切り替え時に確認すること" tabindex="-1">切り替え時に確認すること <a class="header-anchor" href="#切り替え時に確認すること" aria-label="Permalink to &quot;切り替え時に確認すること&quot;">​</a></h2><ol><li>今の状態で、その遷移を受け付けてよいかを調べる。</li><li>今の状態で使っていた操作や表示を終了する。</li><li>次の状態のデータ、入力、表示を用意する。</li><li>更新や通知が、次の状態の前提で動くことを確認する。</li></ol><p>例えばリトライでは、HPを戻す、前の弾を片付ける、スコアを初期化するといった準備が必要です。状態の名前を変える処理と、ゲームを再開できるように準備する処理を、両方追います。<a href="/study/game/basics/prefabs-and-object-lifetimes.html">プレハブとオブジェクトの寿命</a> · <a href="/study/game/basics/game-events-and-notifications.html">ゲーム内イベントと通知</a></p><p>より細かな状態の組み合わせや実装は、<a href="/study/game/patterns/state-machines.html">有限ステートマシンと階層型ステートマシン</a>へ進みます。</p>',17)])])}const p=t(n,[["render",d]]);export{u as __pageData,p as default};
